const PE_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=360,ex='')=>{const p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push([x0+(x1-x0)*i/n,yc-k*f(t)])}return PE_poly(p,col,w,ex)};
/* the sine-triangle comparator over one output cycle (th in degrees): carrier peak 1, m_f carrier periods per cycle */
const PE_rad=d=>d*Math.PI/180;
const PE_tri=(th,mf)=>{const p=(th/360*mf)%1;return 1-4*Math.abs(p-.5)};          // +1 at the start of each carrier period, −1 in the middle
