function W9(d){return d/360*560}
function EXTRA(R,ICON){
 /* hook: the switches' hard pulses (computed bipolar comparator output) and the smooth wave the motor runs on */
 ICON.peHkPulse=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${PE_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${PE_T(20,36,'switches: on or off',{fs:24,fill:BLU})}${PE_L(20,104,360,104,PE_AX,1.5)}${PE_wave(th=>PE_bip(th,.8,9),20,360,104,38,BLU,3,900)}</g>`;
 ICON.peHkSine=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${PE_box(0,0,380,160,{fill:'#FFFFFF',st:GRN,sw:3,r:18})}${PE_T(20,36,'motor: a smooth 50 Hz wave',{fs:24,fill:GRN})}${PE_L(20,104,360,104,PE_AX,1.5)}${PE_curve(th=>Math.sin(PE_rad(th)),0,360,20,360,104,40,GRN,5)}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.peSpwm=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="320" rx="18" fill="#EDF2FF"/>${PE_L(10,100,410,100,PE_AX,1.5)}${PE_curve(th=>PE_tri(th,9),0,360,10,410,100,70,'#9AA5B8',2,720)}${PE_curve(th=>.8*Math.sin(PE_rad(th)),0,360,10,410,100,70,BLU,5)}${PE_L(10,260,410,260,PE_AX,1.5)}${PE_wave(th=>PE_uni(th,.8,9),10,410,260,50,ORG,3)}</g>`;
 ICON.peHex=(x,y)=>{const cx=210,cy=170,R=140;let s=PE_poly(PE_hexPts(cx,cy,R),'#8C96AA',3);[0,1,2,3,4,5].forEach(i=>{const a=PE_rad(60*i);s+=PE_arrow(cx,cy,cx+R*Math.cos(a),cy-R*Math.sin(a),i<2?ORG:'#8C96AA',i<2?5:3)});
  s+=`<circle cx="${cx}" cy="${cy}" r="${(R*Math.cos(PE_rad(30))).toFixed(1)}" fill="none" stroke="${GRN}" stroke-width="3" stroke-dasharray="8 6"/>`+PE_arrow(cx,cy,cx+105*Math.cos(PE_rad(20)),cy-105*Math.sin(PE_rad(20)),GRN,6);
  return `<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="320" rx="18" fill="#FFF4E6"/>${s}</g>`};
 ICON.peShe=(x,y)=>{const f=n=>Math.abs(1-2*Math.cos(PE_rad(n*23.64))+2*Math.cos(PE_rad(n*33.33)))/n;let s=PE_L(20,290,410,290,PE_MUT,2);
  [1,3,5,7,9,11].forEach((n,i)=>{const x0=40+i*64;s+=`<rect x="${x0}" y="${(290-200/n).toFixed(1)}" width="22" height="${(200/n).toFixed(1)}" fill="#DEE2E6"/>`;const h=200*f(n);if(h>2)s+=`<rect x="${x0+24}" y="${(290-h).toFixed(1)}" width="22" height="${h.toFixed(1)}" fill="${GRN}"/>`;else s+=PE_T(x0+35,282,'0',{fs:26,a:'middle',fill:GRN,fw:800});s+=PE_T(x0+23,322,String(n),{fs:24,a:'middle',fill:PE_MUT})});
  return `<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="320" rx="18" fill="#EBFBEE"/>${s}</g>`};
}
